\begin{tikzpicture}[font=\sffamily, line width=0.4pt]
  % cell wall
  \draw[line width=2.2pt, rounded corners=12pt] (0,0) rectangle (5,7);
  % cell membrane with lightly shaded cytoplasm
  \filldraw[fill=black!8, draw=black, rounded corners=9pt] (0.2,0.2) rectangle (4.8,6.8);
  % large central vacuole
  \draw (2.7,3.0) ellipse (1.4 and 1.6);
  % nucleus with nucleolus, near the top
  \draw (1.4,5.7) circle (0.45);
  \fill[black!40] (1.45,5.75) circle (0.15);
  % about ten chloroplasts around the edges
  \foreach \p in {(2.5,0.6),(0.75,0.8),(4.3,0.8),(0.75,2.4),(4.35,2.2),(0.75,4.2),(4.35,4.1),(3.9,6.1),(2.6,6.4),(4.3,5.4)}
