  % label lines and letters
  \draw (0,3.5) -- (-0.7,3.5);
  \node[anchor=east] at (-0.75,3.5) {A};
  \draw (4.8,5.5) -- (5.6,5.5);
  \node[anchor=west] at (5.65,5.5) {B};
  \draw (4.35,2.2) -- (5.4,1.6);
  \node[anchor=west] at (5.45,1.6) {C};
  \draw (1.2,5.9) -- (0.6,7.3);
  \node[anchor=south] at (0.6,7.35) {D};
  \draw (4.1,3.0) -- (5.4,2.9);
  \node[anchor=west] at (5.45,2.9) {E};
  % caption
  \node[anchor=north] at (2.5,-0.5) {Fig. 1.1};
\end{tikzpicture}
